/* Shared settings parsers, loaded before career validation and migration. */
function parseLotteryChances(value){if(typeof value!=='string'||value.length>600||!value.trim())throw Error('Enter comma-separated lottery weights.');const parts=value.split(',').map(s=>s.trim());if(parts.length>36||parts.some(s=>!/^\d+(\.\d+)?$/.test(s)))throw Error('Lottery chances need up to 36 non-negative numbers separated by commas.');const weights=parts.map(Number);if(weights.some(n=>!Number.isFinite(n)||n>1000000)||!weights.some(n=>n>0))throw Error('Lottery weights must total more than zero and each be at most 1,000,000.');return weights}
